import type { CapacitorKmpPlugin, EchoOptions, EchoResult, KmpInfo } from './definitions';
import { KmpWebPlugin } from './kmp-web';

export class CapacitorKmpWeb extends KmpWebPlugin implements CapacitorKmpPlugin {
  constructor() {
    // Kotlin/JS output of kmp/core (generated by `npm run kmp:build`).
    super(() => import('./generated/kmp/capacitor-kmp-core.mjs').then((m) => m.createCoreInfoBridge()));
  }

  getKmpInfo(): Promise<KmpInfo> {
    return this.invoke('getKmpInfo');
  }

  echo(options: EchoOptions): Promise<EchoResult> {
    return this.invoke('echo', options);
  }
}
